+static KConfigGroup albumsGroup()
+{
+    return KConfigGroup(KSharedConfig::openConfig(QStringLiteral("plasmarc")), QStringLiteral("Wallpaper Albums"));
+}
+
+QStringList ImageBackend::albums() const
+{
+    QStringList albums = albumsGroup().keyList();
+    albums.sort(Qt::CaseInsensitive);
+    return albums;
+}
+
+QStringList ImageBackend::albumImages(const QString &album) const
+{
+    return albumsGroup().readEntry(album, QStringList());
+}
+
+bool ImageBackend::createAlbum(const QString &album)
+{
+    KConfigGroup group = albumsGroup();
+    if (album.trimmed().isEmpty() || group.hasKey(album)) {
+        return false;
+    }
+
+    group.writeEntry(album, QStringList());
+    group.sync();
+    Q_EMIT albumsChanged();
+    return true;
+}
+
+void ImageBackend::removeAlbum(const QString &album)
+{
+    KConfigGroup group = albumsGroup();
+    if (!group.hasKey(album)) {
+        return;
+    }
+
+    group.deleteEntry(album);
+    group.sync();
+    Q_EMIT albumsChanged();
+}
+
+void ImageBackend::setInAlbum(const QString &album, const QString &image, bool inAlbum)
+{
+    KConfigGroup group = albumsGroup();
+    if (!group.hasKey(album) || image.isEmpty()) {
+        return;
+    }
+
+    QStringList images = group.readEntry(album, QStringList());
+    if (images.contains(image) == inAlbum) {
+        return;
+    }
+
+    if (inAlbum) {
+        images.append(image);
+    } else {
+        images.removeAll(image);
+    }
+    group.writeEntry(album, images);
+    group.sync();
+    Q_EMIT albumsChanged();
+}
